update public.ce_course3_catalog set metadata='{"id": "1047243", "title": "Legal Essentials for the CRNA", "credits": 20.0, "approval_statement": "This program has been prior approved by the American Association of Nurse Anesthesiology for 20.00 MAC Ed CE credits; Code Number 1047243; Expiration Date 9/30/2029.", "starts": "2026-10-01", "expires": "2029-09-30", "contact": "info@cehalo.com", "module": {"id": "course_3_module_1", "number": 1, "title": "Scope of Practice Laws for the CRNA", "short_title": "Scope of Practice Laws", "credits": 2.0, "pharmacology_credits": 0.0, "pain_credits": 0.0, "objectives": ["Define CRNA scope of practice and distinguish it from individual competence, credentialing, privileging, and facility policy, applying the 2026 AANA Scope of Nurse Anesthesia Practice framework.", "Describe the primary legal sources that govern CRNA practice, including state nurse practice acts, board of nursing rules, federal Medicare Conditions of Participation (42 CFR §482.52), and controlled-substance regulations (21 CFR §1301).", "Explain the significance of the Centers for Medicare & Medicaid Services physician-supervision opt-out and how it differs from state full practice authority, using the current AANA opt-out list (27 states plus Guam as of July 2026).", "Compare independent practice, collaborative practice, supervision, and transition-to-practice models using the NCSBN Independent vs Not Independent APRN classification and identify how each applies to CRNA authority.", "Identify strategies for maintaining legal compliance when practicing across multiple states or practice settings, including licensure verification, DEA registration, malpractice coverage, and facility privileging considerations.", "Differentiate anesthesia practice authority from prescriptive authority, including considerations for outpatient prescribing, controlled-substance requirements, and prescription drug monitoring program (PDMP) obligations.", "Locate and evaluate current state-specific CRNA laws using nurse practice acts, board of nursing guidance, controlled-substance rules, federal requirements, and professional resources such as AANA state practice information and the NCSBN Independent Practice Map.", "Apply scope-of-practice principles to common clinical and administrative scenarios involving anesthesia planning, medication administration, prescriptive authority, documentation, and interdisciplinary communication, using a structured decision-making framework."], "evaluation_items": ["The facilitator was effective in presenting the material.", "Teaching methods were effective.", "Online learning format facilitated learning.", "The content was related to the objectives.", "My personal learning objectives were met."], "rating_scale": {"1": "Excellent", "2": "Good", "3": "Adequate", "4": "Fair", "5": "Poor"}, "rating_scale_description": "Rate each item: 1 Excellent, 2 Good, 3 Adequate, 4 Fair, 5 Poor. All ratings and written responses are required.", "question_count": 15, "bank_size": 25, "passing_score": 12, "max_attempts": 3, "resource_prefix": "course3_module1", "page_count": 26, "document_sha256": "f2fdffb8bb05047ad0764fd2e365e64cb3aa46f35a1f12fa664f6a2a67afd669", "content_status": "provider_authorized_final"}, "modules": [{"id": "course_3_module_1", "number": 1, "title": "Scope of Practice Laws for the CRNA", "short_title": "Scope of Practice Laws", "credits": 2.0, "pharmacology_credits": 0.0, "pain_credits": 0.0, "objectives": ["Define CRNA scope of practice and distinguish it from individual competence, credentialing, privileging, and facility policy, applying the 2026 AANA Scope of Nurse Anesthesia Practice framework.", "Describe the primary legal sources that govern CRNA practice, including state nurse practice acts, board of nursing rules, federal Medicare Conditions of Participation (42 CFR §482.52), and controlled-substance regulations (21 CFR §1301).", "Explain the significance of the Centers for Medicare & Medicaid Services physician-supervision opt-out and how it differs from state full practice authority, using the current AANA opt-out list (27 states plus Guam as of July 2026).", "Compare independent practice, collaborative practice, supervision, and transition-to-practice models using the NCSBN Independent vs Not Independent APRN classification and identify how each applies to CRNA authority.", "Identify strategies for maintaining legal compliance when practicing across multiple states or practice settings, including licensure verification, DEA registration, malpractice coverage, and facility privileging considerations.", "Differentiate anesthesia practice authority from prescriptive authority, including considerations for outpatient prescribing, controlled-substance requirements, and prescription drug monitoring program (PDMP) obligations.", "Locate and evaluate current state-specific CRNA laws using nurse practice acts, board of nursing guidance, controlled-substance rules, federal requirements, and professional resources such as AANA state practice information and the NCSBN Independent Practice Map.", "Apply scope-of-practice principles to common clinical and administrative scenarios involving anesthesia planning, medication administration, prescriptive authority, documentation, and interdisciplinary communication, using a structured decision-making framework."], "evaluation_items": ["The facilitator was effective in presenting the material.", "Teaching methods were effective.", "Online learning format facilitated learning.", "The content was related to the objectives.", "My personal learning objectives were met."], "rating_scale": {"1": "Excellent", "2": "Good", "3": "Adequate", "4": "Fair", "5": "Poor"}, "rating_scale_description": "Rate each item: 1 Excellent, 2 Good, 3 Adequate, 4 Fair, 5 Poor. All ratings and written responses are required.", "question_count": 15, "bank_size": 25, "passing_score": 12, "max_attempts": 3, "resource_prefix": "course3_module1", "page_count": 26, "document_sha256": "f2fdffb8bb05047ad0764fd2e365e64cb3aa46f35a1f12fa664f6a2a67afd669", "content_status": "provider_authorized_final"}, {"id": "course_3_module_2", "number": 2, "title": "Informed Consent for Anesthesia Care", "short_title": "Informed Consent", "credits": 2.0, "pharmacology_credits": 0.0, "pain_credits": 0.0, "objectives": ["Define informed consent for anesthesia care as a communication process — including disclosure, understanding, voluntariness, decision-making capacity, and authorization — rather than a signature on a form.", "Differentiate anesthesia informed consent from surgical or procedural consent, and describe how anesthesia-specific risks must be documented under 42 CFR §482.51(b)(2) and applicable facility policy.", "Apply AANA Standard 4 (Informed Consent for Anesthesia Care and Related Services), Standard 2 (Preanesthesia Patient Assessment and Evaluation), and Standard 3 (Plan for Anesthesia Care) to identify the CRNA''s individual consent responsibilities.", "Identify who may obtain, sign, and witness the anesthesia consent — including the CRNA, anesthesiologist, patient, and legally authorized representative — in accordance with state law, facility policy, and medical staff bylaws.", "Describe documentation standards for anesthesia informed consent, including the elements required by the April 2024 CMS revised hospital interpretive guidance and 42 CFR §482.24(c)(4)(v).", "Recognize anesthesia-specific material risks that should be discussed for general anesthesia, monitored anesthesia care, neuraxial anesthesia, peripheral nerve blocks, and obstetric anesthesia.", "Apply informed-consent principles to special situations — including emergencies, capacity concerns, language and health literacy barriers, changes in the anesthesia plan, pregnant minors, and informed refusal — and identify appropriate documentation for each.", "Explain CRNA liability exposure related to inadequate consent, improper delegation, incomplete documentation, and sensitive-examination disclosure requirements, and implement risk-management strategies that reduce medico-legal exposure."], "evaluation_items": ["The facilitator was effective in presenting the material.", "Teaching methods were effective.", "Online learning format facilitated learning.", "The content was related to the objectives.", "My personal learning objectives were met."], "rating_scale": {"1": "Excellent", "2": "Good", "3": "Adequate", "4": "Fair", "5": "Poor"}, "rating_scale_description": "Rate each item: 1 Excellent, 2 Good, 3 Adequate, 4 Fair, 5 Poor. All ratings and written responses are required.", "question_count": 15, "bank_size": 25, "passing_score": 12, "max_attempts": 3, "resource_prefix": "course3_module2", "page_count": 25, "document_sha256": "895baf065037c9ac82ea55d709b9c9526eb4570338ce68edc80758d6d4637c94", "content_status": "provider_authorized_final"}, {"id": "course_3_module_3", "number": 3, "title": "Documentation and Charting Liability for the CRNA", "short_title": "Documentation and Charting Liability", "credits": 2.0, "pharmacology_credits": 0.0, "pain_credits": 0.0, "objectives": ["Explain the purposes of legal anesthesia documentation — patient safety, clinical communication, reimbursement, regulatory compliance, and liability defense — and describe how the anesthesia record functions as the CRNA''s most reliable perioperative account.", "Compare AANA documentation expectations (Standards for Nurse Anesthesia Practice, 2019), ASA documentation standards (2024), and CMS anesthesia documentation requirements under 42 CFR §482.52 as applied by the CMS Appendix A Interpretive Guidelines.", "Identify the essential elements of preanesthesia, intraoperative, and postanesthesia documentation, including the CMS timing requirements for preanesthesia evaluation (within 48 hours before) and postanesthesia evaluation (within 48 hours after) surgery or the procedure.", "Recognize high-risk documentation areas commonly scrutinized in malpractice claims, peer review, board investigations, NPDB-related matters, and payer audits — including difficult airway, medication errors, hemodynamic events, handoffs, and discharge readiness.", "Apply the observation–interpretation–action–response–plan format to document clinical judgment in anesthesia care, and describe how such notes demonstrate recognition, decision-making, intervention, and reassessment.", "Describe defensible practices for late entries, corrections, addenda, and amendments — including transparency, clear identification, date/time/author, and avoidance of concealment or backdating, per The Joint Commission RC.01.03.01 and facility policy.", "Identify electronic health record (EHR) charting pitfalls — including copy-forward, default normal findings, contradictory entries, template misuse, unresolved artifacts, and information-blocking / open-notes considerations under the 21st Century Cures Act — and apply mitigation strategies.", "Distinguish the role of the medical record from the institutional incident report, and apply best practices for documenting emergencies, adverse events, communications, and follow-up in a manner that supports patient safety and reduces liability exposure."], "evaluation_items": ["The facilitator was effective in presenting the material.", "Teaching methods were effective.", "Online learning format facilitated learning.", "The content was related to the objectives.", "My personal learning objectives were met."], "rating_scale": {"1": "Excellent", "2": "Good", "3": "Adequate", "4": "Fair", "5": "Poor"}, "rating_scale_description": "Rate each item: 1 Excellent, 2 Good, 3 Adequate, 4 Fair, 5 Poor. All ratings and written responses are required.", "question_count": 15, "bank_size": 25, "passing_score": 12, "max_attempts": 3, "resource_prefix": "course3_module3", "page_count": 22, "document_sha256": "4c855726ef9946a77cb8b3ce5c3b10cde578331a6c33107c18cd44fe4b1285d4", "content_status": "provider_authorized_final"}, {"id": "course_3_module_4", "number": 4, "title": "Standards of Care: AANA vs. ASA", "short_title": "Standards of Care: AANA vs. ASA", "credits": 1.5, "pharmacology_credits": 0.0, "pain_credits": 0.0, "objectives": ["Describe the purpose, sources, and legal weight of anesthesia standards of care and distinguish them from guidelines, position statements, facility policies, and individual competence.", "Identify each of the 14 AANA Standards for Nurse Anesthesia Practice and explain how each standard applies to CRNA responsibilities across the preoperative, intraoperative, and postoperative phases of care.", "Summarize the current ASA Standards for Basic Anesthetic Monitoring — including personnel presence, oxygenation, ventilation, circulation, and temperature monitoring requirements — and describe the conditions under which each standard may be modified.", "Compare AANA Standards for Nurse Anesthesia Practice and ASA Standards for Basic Anesthetic Monitoring side by side across focus, applicability, personnel, monitoring, equipment, and documentation domains.", "Analyze the legal, regulatory, credentialing, and malpractice implications of professional standards in relation to state nurse practice acts, CMS Conditions of Participation, Joint Commission requirements, and facility bylaws.", "Apply standards-based decision-making to special anesthesia environments — office-based anesthesia, nonoperating room anesthesia (NORA), obstetric anesthesia, regional anesthesia, and mass casualty or crisis conditions — where environmental risk factors may require additional planning and safeguards.", "Describe the current ASRA/ESRA 2024 recommendations for prevention, recognition, and treatment of local anesthetic systemic toxicity (LAST), including the updated LAST checklist and lipid emulsion dosing.", "Use a structured framework to document adherence to, or justified deviation from, professional standards in routine and emergency anesthesia practice."], "evaluation_items": ["The facilitator was effective in presenting the material.", "Teaching methods were effective.", "Online learning format facilitated learning.", "The content was related to the objectives.", "My personal learning objectives were met."], "rating_scale": {"1": "Excellent", "2": "Good", "3": "Adequate", "4": "Fair", "5": "Poor"}, "rating_scale_description": "Rate each item: 1 Excellent, 2 Good, 3 Adequate, 4 Fair, 5 Poor. All ratings and written responses are required.", "question_count": 15, "bank_size": 25, "passing_score": 12, "max_attempts": 3, "resource_prefix": "course3_module4", "page_count": 27, "document_sha256": "b65305d2c3aad20813316abdf691052b2ea1383c1ac0dc6e0d5eedd6af9a0e7f", "content_status": "provider_authorized_final"}, {"id": "course_3_module_5", "number": 5, "title": "Medication Errors & the Anesthesia Provider", "short_title": "Medication Errors", "credits": 2.0, "pharmacology_credits": 0.0, "pain_credits": 0.0, "objectives": ["Differentiate active errors, latent errors, slips, mistakes, near misses, adverse drug events, and high-alert medication events as they apply to nurse anesthesia practice.", "Identify high-risk CRNA medication scenarios across induction, maintenance, emergence, regional and neuraxial anesthesia, obstetrics, pediatrics, procedural sedation, and nonoperating-room anesthesia (NORA).", "Analyze the root causes of anesthesia medication errors using a systems-based framework that addresses human factors, medication factors, workflow, technology, environment, and organizational culture.", "Apply the 2024 Anesthesia Patient Safety Foundation (APSF) Stoelting Consensus Recommendations and the APSF STPC framework (Standardization, Technology, Pharmacy/prefilled syringes, Culture) to perioperative medication-safety decisions.", "Recognize look-alike/sound-alike (LASA) drug pairs that most commonly cause wrong-drug and wrong-route events in anesthesia, including tranexamic acid vs. local anesthetic; neuromuscular blocker vs. antibiotic or antiemetic; and hydromorphone vs. morphine.", "Describe legal standards of care, negligence elements (duty, breach, causation, damages), documentation duties, and vicarious-liability exposure for CRNAs after a medication error.", "Apply Just Culture principles to distinguish human error, at-risk behavior, and reckless conduct, and explain how the 2022 RaDonda Vaught criminal case reshaped the medication-error response conversation for advanced practice nurses.", "Implement post-error risk-reduction, disclosure, and reporting workflows using ISMP High-Alert Medications, ISMP MERP, FDA MedWatch, The Joint Commission National Patient Safety Goals, and facility patient-safety systems."], "evaluation_items": ["The facilitator was effective in presenting the material.", "Teaching methods were effective.", "Online learning format facilitated learning.", "The content was related to the objectives.", "My personal learning objectives were met."], "rating_scale": {"1": "Excellent", "2": "Good", "3": "Adequate", "4": "Fair", "5": "Poor"}, "rating_scale_description": "Rate each item: 1 Excellent, 2 Good, 3 Adequate, 4 Fair, 5 Poor. All ratings and written responses are required.", "question_count": 15, "bank_size": 25, "passing_score": 12, "max_attempts": 3, "resource_prefix": "course3_module5", "page_count": 30, "document_sha256": "a9d205920a036981e68f866d8e4fcffe6b0049ea19673b63b618d44f570b7c82", "content_status": "provider_authorized_final"}, {"id": "course_3_module_6", "number": 6, "title": "Malpractice Claims Against CRNAs", "short_title": "Malpractice Claims", "credits": 2.0, "pharmacology_credits": 0.0, "pain_credits": 0.0, "objectives": ["Explain why anesthesia practice is associated with high-severity malpractice exposure despite decades of patient safety gains, using contemporary closed-claims data from the ASA Closed Claims Project, the AANA Foundation Malpractice Closed Claims Study, and 2026 National Practitioner Data Bank analyses of CRNA and physician anesthesia claims.", "Identify and apply the four legal elements of a professional negligence claim — duty, breach, causation, and damages — to CRNA clinical scenarios and describe how each element is proved through the anesthesia record, professional standards, and expert testimony.", "Recognize the most common categories of malpractice allegations against CRNAs, including airway and respiratory events, positioning and peripheral nerve injury, dental injury, medication and dosing errors, monitoring failures, intraoperative awareness, regional-anesthesia complications, and post-anesthesia care failures.", "Differentiate individual CRNA liability from vicarious liability, corporate negligence, and captain-of-the-ship or borrowed-servant doctrines, and describe how supervision, medical direction, and collaboration arrangements affect allocation of responsibility.", "Describe how plaintiffs build an anesthesia malpractice case using timelines, capnography and monitor data, institutional policies, and expert opinion, and how CRNAs and defense counsel construct rebuttal strategies grounded in standard-of-care compliance, known complications, causation, timely rescue, and contemporaneous documentation.", "Compare occurrence, claims-made, tail (extended reporting), and prior-acts (nose) professional-liability coverage; interpret per-claim and aggregate limits, inside- vs. outside-limits defense costs, shared vs. individual limits, and consent-to-settle and hammer-clause provisions.", "Evaluate how much malpractice coverage a CRNA may need based on practice model (W-2 employee, 1099 contractor, locum tenens, solo/office-based, moonlighting), patient acuity, jurisdictional verdict environment, license-defense needs, and current 2024–2026 indemnity payment trends.", "Apply structured risk-reduction, documentation, and communication strategies to real-life anesthesia malpractice case studies involving delayed airway rescue, missed cardiac risk, PACU respiratory deterioration, intraoperative awareness, ambulatory arrest, obstetric hemorrhage, and licensing-board defense."], "evaluation_items": ["The facilitator was effective in presenting the material.", "Teaching methods were effective.", "Online learning format facilitated learning.", "The content was related to the objectives.", "My personal learning objectives were met."], "rating_scale": {"1": "Excellent", "2": "Good", "3": "Adequate", "4": "Fair", "5": "Poor"}, "rating_scale_description": "Rate each item: 1 Excellent, 2 Good, 3 Adequate, 4 Fair, 5 Poor. All ratings and written responses are required.", "question_count": 15, "bank_size": 25, "passing_score": 12, "max_attempts": 3, "resource_prefix": "course3_module6", "page_count": 28, "document_sha256": "2faf41ec9e13503cc0c24f49a93522e1a531fa454f4d9a874a34cbcc467152d4", "content_status": "provider_authorized_final"}, {"id": "course_3_module_7", "number": 7, "title": "Airway Management Liability", "short_title": "Airway Management Liability", "credits": 2.0, "pharmacology_credits": 0.0, "pain_credits": 0.0, "objectives": ["Describe the legal duty, breach, causation, and damages framework as it applies to CRNA airway assessment, planning, intervention, rescue, monitoring, and documentation.", "Identify the most common airway-related allegations in closed-claims analyses of anesthesia malpractice, including failure to assess, failure to plan, failure to rescue, delayed recognition of hypoxia/hypoventilation, and inadequate documentation.", "Apply the 2022 American Society of Anesthesiologists (ASA) Practice Guidelines for Management of the Difficult Airway and the Difficult Airway Society (DAS) Plan A/B/C/D framework to anticipated and unanticipated difficult airway scenarios.", "Explain the evolving standard of care surrounding video laryngoscopy as a first-choice device for anticipated difficult airways, and the medico-legal implications of failing to use available advanced airway equipment.", "Recognize equipment, monitoring, sedation, and non–operating room anesthesia (NORA) factors that increase airway liability risk, including the role of waveform capnography and immediate airway-rescue readiness.", "Analyze liability specific to dental injury claims, failed extubation, post-operative airway obstruction, and the physiologically difficult airway.", "Use documentation strategies — including preoperative airway assessment, primary/backup airway plan, awake fiberoptic and awake tracheostomy consideration, time-based emergency entries, and post-event disclosure — that demonstrate clinical judgment and adherence to standards of care.", "Apply a structured cognitive-aid framework (ASA algorithm, DAS Plan A–D, and the Vortex Approach) to declare and manage a ''cannot intubate, cannot oxygenate'' (CICO) emergency, including timely emergency front-of-neck access (eFONA)."], "evaluation_items": ["The facilitator was effective in presenting the material.", "Teaching methods were effective.", "Online learning format facilitated learning.", "The content was related to the objectives.", "My personal learning objectives were met."], "rating_scale": {"1": "Excellent", "2": "Good", "3": "Adequate", "4": "Fair", "5": "Poor"}, "rating_scale_description": "Rate each item: 1 Excellent, 2 Good, 3 Adequate, 4 Fair, 5 Poor. All ratings and written responses are required.", "question_count": 15, "bank_size": 25, "passing_score": 12, "max_attempts": 3, "resource_prefix": "course3_module7", "page_count": 27, "document_sha256": "3193c5a128d50976ba8d28b78ef7cb8bb14369f8d812022428795b443fbe7a2d", "content_status": "provider_authorized_final"}, {"id": "course_3_module_8", "number": 8, "title": "Obstetric Anesthesia Liability", "short_title": "Obstetric Anesthesia Liability", "credits": 2.0, "pharmacology_credits": 0.0, "pain_credits": 0.0, "objectives": ["Explain why obstetric anesthesia carries disproportionate professional liability exposure for CRNAs and interpret current U.S. maternal mortality trends (CDC 2022–2024 data) and the role of anesthesia care in preventable maternal death and severe maternal morbidity.", "Apply ASHRM-informed, SOAP-endorsed, and ACOG-endorsed risk-management principles — including standardization, closed-loop communication, contemporaneous documentation, event reporting, disclosure, multidisciplinary simulation, and coordinated claims readiness — to everyday CRNA obstetric anesthesia practice.", "Identify obstetric airway liability risks and describe evidence-based CRNA strategies for difficult-airway preparation, aspiration prevention, failed-intubation response, and safe conversion from neuraxial to general anesthesia during emergency cesarean delivery.", "Recognize hemorrhage-related liability risk and outline preparation for massive transfusion, maternal resuscitation, blood-product planning, and escalation using ACOG Practice Bulletin 183 / AIM Safety Bundle principles during postpartum hemorrhage and placenta accreta spectrum.", "Evaluate neuraxial anesthesia complications — including failed or inadequate block, high or total spinal, local anesthetic systemic toxicity (LAST), post-dural puncture headache, epidural hematoma, infection, medication error, and postpartum neurologic deficit — using the 2023 ASA Statement on Neurologic Complications of Neuraxial Analgesia/Anesthesia in Obstetrics and the 2021 SOAP Thrombocytopenia Consensus.", "Describe amniotic fluid embolism (AFE) recognition, differential diagnosis, and coordinated maternal cardiac-arrest response consistent with the SOAP/AHA (2014, updated 2023) consensus on cardiac arrest in pregnancy, including 4-minute perimortem cesarean decision-making.", "Analyze anesthesia liability arising from emergency cesarean delivery — including decision-to-incision time, urgency classification, failed epidural conversion, general anesthesia risk, intraoperative pain, awareness, and post-event follow-up — with reference to CRNA response time expectations.", "Develop anesthesia planning priorities for high-risk obstetric patients (severe preeclampsia/HELLP, cardiac disease, obesity/OSA, placenta accreta spectrum, coagulopathy, sepsis, pulmonary hypertension, VBAC/TOLAC, and substance use disorder), incorporating VBAC anesthesia standby requirements per ACOG Practice Bulletin 205.", "Integrate culturally responsive, trauma-informed, and health-literacy-appropriate informed-consent practices into obstetric anesthesia care, recognizing consent limitations in the laboring patient and the role of qualified interpreters and teach-back methodology.", "Use current closed-claims data (ASA Closed Claims Project, AANA Foundation Closed Claims, and Kovacheva 2019 medicolegal review) to identify preventable risk patterns and translate them into CRNA documentation, escalation, and team-based patient-safety practices."], "evaluation_items": ["The facilitator was effective in presenting the material.", "Teaching methods were effective.", "Online learning format facilitated learning.", "The content was related to the objectives.", "My personal learning objectives were met."], "rating_scale": {"1": "Excellent", "2": "Good", "3": "Adequate", "4": "Fair", "5": "Poor"}, "rating_scale_description": "Rate each item: 1 Excellent, 2 Good, 3 Adequate, 4 Fair, 5 Poor. All ratings and written responses are required.", "question_count": 15, "bank_size": 25, "passing_score": 12, "max_attempts": 3, "resource_prefix": "course3_module8", "page_count": 31, "document_sha256": "843fb75317d453d45fd263234acedcd715a3e461a52f18ec7e4644847cee41d0", "content_status": "provider_authorized_final"}, {"id": "course_3_module_9", "number": 9, "title": "HIPAA & Patient Privacy in Anesthesia Practice", "short_title": "HIPAA and Patient Privacy", "credits": 1.75, "pharmacology_credits": 0.0, "pain_credits": 0.0, "objectives": ["Differentiate the HIPAA Privacy Rule, Security Rule, and Breach Notification Rule as they apply to Certified Registered Nurse Anesthetist (CRNA) practice, including the 2024 Security Rule Notice of Proposed Rulemaking updates.", "Apply the minimum necessary standard, treatment-payment-operations disclosure permissions, and patient-rights principles to common anesthesia care scenarios (preoperative, intraoperative, PACU, and non-operating-room settings).", "Identify privacy and security risks in anesthesia workflows involving documentation, verbal handoffs, electronic health records, mobile devices, text messaging, social media, clinical photography, and teaching.", "Describe federal enforcement structure, HITECH Act civil monetary penalty tiers, criminal liability, breach notification timelines, and Office for Civil Rights (OCR) enforcement trends, including the 2024 Change Healthcare cyberattack and Right of Access Initiative settlements.", "Analyze real-world HIPAA cases (employee snooping, workforce sanctions, social-media disclosures, ransomware, and unauthorized third-party disclosures) and apply the lessons to anesthesia documentation, communication, and EHR access practices.", "Explain the role of Business Associate Agreements (BAAs) in anesthesia practice, including obligations of vendors handling anesthesia information management systems (AIMS), transcription, billing, secure-messaging, and electronic-health-record services.", "Implement a privacy-conscious action plan for preventing, recognizing, and reporting suspected HIPAA violations, and for responding to ransomware, device loss, mis-directed communications, and workforce snooping incidents in anesthesia practice."], "evaluation_items": ["The facilitator was effective in presenting the material.", "Teaching methods were effective.", "Online learning format facilitated learning.", "The content was related to the objectives.", "My personal learning objectives were met."], "rating_scale": {"1": "Excellent", "2": "Good", "3": "Adequate", "4": "Fair", "5": "Poor"}, "rating_scale_description": "Rate each item: 1 Excellent, 2 Good, 3 Adequate, 4 Fair, 5 Poor. All ratings and written responses are required.", "question_count": 15, "bank_size": 25, "passing_score": 12, "max_attempts": 3, "resource_prefix": "course3_module9", "page_count": 31, "document_sha256": "6c6f02fc331cc26c473332c000030baee429ca6b930681c32746bf13832f1fb4", "content_status": "provider_authorized_final"}, {"id": "course_3_module_10", "number": 10, "title": "The CRNA as Expert Witness", "short_title": "Expert Witness Testimony", "credits": 1.25, "pharmacology_credits": 0.0, "pain_credits": 0.0, "objectives": ["Describe the purpose, role, neutrality obligations, and scope boundaries of the CRNA expert witness, and distinguish fact-witness testimony from expert-opinion testimony.", "Identify current professional, clinical, and ethical qualifications expected of a CRNA expert witness, including licensure, certification, clinical relevance, and CV / publication preparation.", "Compare the Daubert (Federal Rules of Evidence 702 and 703) and Frye “general acceptance” admissibility standards and explain the December 1, 2023 amendment to FRE 702 and its practical impact on CRNA expert testimony.", "Explain the Federal Rule of Civil Procedure 26(a)(2)(B) report requirements and describe how a CRNA expert prepares a compliant written expert report.", "Contrast retention by plaintiff versus defense counsel, including conflict screening, disclosure of prior testimony, retention letter elements, and duties of impartiality regardless of retaining party.", "Apply the AANA Expert Witness Testimony Guidelines and Code of Ethics to ethical challenges CRNA experts encounter, including fee structures, the prohibition on contingency fees, and avoiding advocacy.", "Differentiate deposition testimony from trial testimony and describe preparation strategies for direct examination, cross-examination, and voir dire challenges to expert qualifications.", "Analyze anesthesia records, timelines, causation, and system factors using a disciplined case-analysis framework consistent with FRE 702 reliability requirements and current AANA professional standards."], "evaluation_items": ["The facilitator was effective in presenting the material.", "Teaching methods were effective.", "Online learning format facilitated learning.", "The content was related to the objectives.", "My personal learning objectives were met."], "rating_scale": {"1": "Excellent", "2": "Good", "3": "Adequate", "4": "Fair", "5": "Poor"}, "rating_scale_description": "Rate each item: 1 Excellent, 2 Good, 3 Adequate, 4 Fair, 5 Poor. All ratings and written responses are required.", "question_count": 15, "bank_size": 25, "passing_score": 12, "max_attempts": 3, "resource_prefix": "course3_module10", "page_count": 23, "document_sha256": "110ca0bffe92c7e613f0f3b769c33685fdd5c79b34c14bb117ab46101161aee1", "content_status": "provider_authorized_final"}, {"id": "course_3_module_11", "number": 11, "title": "Sentinel Events & Just-Culture Response", "short_title": "Sentinel Events and Root Cause Analysis", "credits": 1.5, "pharmacology_credits": 0.0, "pain_credits": 0.0, "objectives": ["Define sentinel event, adverse event, no-harm event, and close call/near miss using the 2024 Joint Commission Sentinel Event Policy, and describe which events are reviewable under that policy.", "Apply the RCA2 (Root Cause Analysis and Action) framework from the National Patient Safety Foundation to plan a comprehensive systematic analysis after an anesthesia-related sentinel event, including the 55-business-day timeline and action-plan components required by The Joint Commission.", "Distinguish among human error, at-risk behavior, and reckless conduct using the Marx just-culture algorithm, and describe the three duties (produce an outcome, follow a procedural rule, avoid unjustifiable risk) that the model uses to guide event review and provider response.", "Recognize the second-victim phenomenon and describe evidence-based peer support program structures (e.g., forYOU/MISE) that support CRNAs and other clinicians involved in a sentinel event.", "Describe the CANDOR (